// Cash handlers (m5-plan §7.3.3): registers, sessions, movements, close, Z report, counter sales and receipts.

// cashDownload answers a generated file (CSV, XLSX, PDF) as an attachment, never cached.
func cashDownload(w http.ResponseWriter, contentType, name string, b []byte) {
	hd := w.Header()
	hd.Set("Content-Type", contentType)
	hd.Set("Content-Length", strconv.Itoa(len(b)))
	hd.Set("Content-Disposition", `attachment; filename="`+name+`"`)
	hd.Set("Cache-Control", "no-store")
	hd.Set("X-Content-Type-Options", "nosniff")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(b) //nolint:gosec // G705: a file generated by Porto, served as an attachment with nosniff
}

// cashPrint answers a self-contained print page (receipt, Z report): inline styles only, no script, no resource.
func cashPrint(w http.ResponseWriter, contentType string, b []byte) {
	hd := w.Header()
	hd.Set("Content-Type", contentType)
	hd.Set("Content-Length", strconv.Itoa(len(b)))
	hd.Set("Cache-Control", "no-store")
	hd.Set("X-Content-Type-Options", "nosniff")
	if contentType == "application/pdf" {
		hd.Set("Content-Security-Policy", "sandbox; default-src 'none'")
	} else {
		hd.Set("Content-Security-Policy", "default-src 'none'; style-src 'unsafe-inline'")
	}
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(b) //nolint:gosec // G705: templated with html/template (escaped) or a PDF, served with a strict CSP
}

// ListCashRegisters implements api.ServerInterface.
func (h *Handler) ListCashRegisters(w http.ResponseWriter, r *http.Request, marinaID api.MarinaId) {
	rs, err := h.Cash.ListRegisters(r.Context(), principal(r), marinaID)
	if err != nil {
		respond.Error(w, r, err)
		return
	}
	respond.JSON(w, http.StatusOK, view.CashRegisters(rs))
}

// CreateCashRegister implements api.ServerInterface.
func (h *Handler) CreateCashRegister(w http.ResponseWriter, r *http.Request, marinaID api.MarinaId, _ api.CreateCashRegisterParams) {
	var in api.CashRegisterInput
	if !respond.DecodeOrFail(w, r, &in, false) {
		return
	}
	reg, err := h.Cash.CreateRegister(r.Context(), principal(r), marinaID, cash.RegisterInput{Code: in.Code, Name: in.Name, Active: boolOr(in.Active, true)})
	if err != nil {
		respond.Error(w, r, err)
		return
	}
	respond.SetETag(w, reg.Version)
	respond.JSON(w, http.StatusCreated, view.CashRegister(*reg))
}

// UpdateCashRegister implements api.ServerInterface.
func (h *Handler) UpdateCashRegister(w http.ResponseWriter, r *http.Request, marinaID api.MarinaId, id api.CashRegisterId, params api.UpdateCashRegisterParams) {
	ifMatch, ok := respond.IfMatch(w, r, params.IfMatch)
	if !ok {
		return
	}
	var in api.CashRegisterPatch
	if !respond.DecodeOrFail(w, r, &in, false) {
		return
	}
	reg, err := h.Cash.UpdateRegister(r.Context(), principal(r), marinaID, id, ifMatch, cash.RegisterPatch{Name: in.Name, Active: in.Active, IsDefault: in.IsDefault})
	if err != nil {
		respond.Error(w, r, err)
		return
	}
	respond.SetETag(w, reg.Version)
	respond.JSON(w, http.StatusOK, view.CashRegister(*reg))
}

