// CloseCashSession implements api.ServerInterface.
func (h *Handler) CloseCashSession(w http.ResponseWriter, r *http.Request, marinaID api.MarinaId, id api.CashSessionId, params api.CloseCashSessionParams) {
	ifMatch, ok := respond.IfMatch(w, r, params.IfMatch)
	if !ok {
		return
	}
	var in api.CloseCashSessionInput
	if !respond.DecodeOrFail(w, r, &in, false) {
		return
	}
	counted := make([]cash.CountedInput, 0, len(in.Counted))
	for _, c := range in.Counted {
		counted = append(counted, cash.CountedInput{Method: string(c.Method), Amount: money.Cents(c.AmountCents)})
	}
	s, err := h.Cash.CloseSession(r.Context(), principal(r), marinaID, id, ifMatch, counted, str(in.Notes))
	if err != nil {
		respond.Error(w, r, err)
		return
	}
	respond.SetETag(w, s.Version)
	respond.JSON(w, http.StatusOK, view.CashSession(s, true))
}

// GetZReport implements api.ServerInterface.
func (h *Handler) GetZReport(w http.ResponseWriter, r *http.Request, marinaID api.MarinaId, id api.CashSessionId, params api.GetZReportParams) {
	z, err := h.Cash.ZReportOf(r.Context(), principal(r), marinaID, id)
	if err != nil {
		respond.Error(w, r, err)
		return
	}
	if params.Format != nil && *params.Format == api.GetZReportParamsFormatPdf {
		b, err := z.PDF()
		if err != nil {
			respond.Error(w, r, err)
			return
		}
		cashPrint(w, "application/pdf", b)
		return
	}
	b, err := z.HTML()
	if err != nil {
		respond.Error(w, r, err)
		return
	}
	cashPrint(w, "text/html; charset=utf-8", b)
}

// CreateCounterSale implements api.ServerInterface.
func (h *Handler) CreateCounterSale(w http.ResponseWriter, r *http.Request, marinaID api.MarinaId, params api.CreateCounterSaleParams) {
	var in api.CounterSaleInput
	if !respond.DecodeOrFail(w, r, &in, false) {
		return
	}
	lines := make([]cash.CounterSaleLine, 0, len(in.Lines))
	for _, l := range in.Lines {
		cl := cash.CounterSaleLine{ItemID: l.ItemId, QtyMilli: l.QtyMilli}
		if l.UnitCents != nil {
			u := money.Cents(*l.UnitCents)
			cl.Unit = &u
		}
		if l.DiscountCents != nil {
			cl.Discount = money.Cents(*l.DiscountCents)
		}
		lines = append(lines, cl)
	}
	sale := cash.CounterSaleInput{
		CustomerID: str(in.CustomerId), VesselID: str(in.VesselId), Lines: lines, Method: string(in.Payment.Method),
		RegisterID: str(in.Payment.RegisterId), FiscalDocument: in.FiscalDocument, Receipt: string(in.Receipt),
		IdempotencyKey: str(params.IdempotencyKey),
	}
	if in.Payment.AmountCents != nil {
		a := money.Cents(*in.Payment.AmountCents)
		sale.Amount = &a
	}
	res, err := h.Cash.CounterSale(r.Context(), principal(r), marinaID, sale)
	if err != nil {
		respond.Error(w, r, err)
		return
	}
	name := ""
	if res.Charge.CustomerID != "" && h.Collect != nil {
		name = h.Collect.CustomerNames(r.Context(), principal(r), marinaID, []string{res.Charge.CustomerID})[res.Charge.CustomerID]
	}
	url := "/api/admin/v1/marinas/" + marinaID + "/payments/" + res.Payment.ID + "/receipt?format=80"
	respond.JSON(w, http.StatusCreated, view.CounterSale(res, name, url))
}

// GetPaymentReceipt implements api.ServerInterface.
func (h *Handler) GetPaymentReceipt(w http.ResponseWriter, r *http.Request, marinaID api.MarinaId, id api.PaymentId, params api.GetPaymentReceiptParams) {
	b, ct, err := h.Cash.Receipt(r.Context(), principal(r), marinaID, id, str(enumPtr(params.Format)))
	if err != nil {
		respond.Error(w, r, err)
		return
	}
	cashPrint(w, ct, b)
}
